translations.esMX = translations.esES
translations.enGB = translations.enUS
Addon.settingsTranslations = translations

local function ClientTranslations()
    return translations[GetLocale()] or translations.enUS
end

function Addon:SettingsText(key)
    local text = ClientTranslations().text[key] or translations.enUS.text[key]
    return assert(text, "Unknown settings text: " .. tostring(key))
end

function Addon:SettingsGroupName(group)
    return ClientTranslations().groups[group] or translations.enUS.groups[group] or group
end

-- Returns the localized name and description of a feature, falling back to English.
function Addon:FeatureText(feature)
    local localized = ClientTranslations().features[feature.id]
    if localized then return localized[1], localized[2] end
    return feature.name, feature.description
end
